<?php
use App\Application\Identity\MembershipService;use App\Models\Tenant;use App\Models\TenantMembership;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Validation\ValidationException;
uses(RefreshDatabase::class);
test('revocation records actor reason and prevents self revocation',function(){$actor=User::factory()->create();$target=User::factory()->create();$tenant=Tenant::create(['type'=>'BROKER','legal_name'=>'Broker','slug'=>'membership-broker','status'=>'ACTIVE','country_code'=>'CM','currency'=>'XAF','primary_locale'=>'en','settings'=>[]]);$m=TenantMembership::create(['tenant_id'=>$tenant->id,'user_id'=>$target->id,'role_code'=>'BROKER_STAFF','status'=>'ACTIVE']);app(MembershipService::class)->revoke($m,$actor,'Employment ended and access withdrawn');expect($m->refresh()->status)->toBe('REVOKED')->and($m->revoked_by)->toBe($actor->id);$self=TenantMembership::create(['tenant_id'=>$tenant->id,'user_id'=>$actor->id,'role_code'=>'BROKER_ADMIN','status'=>'ACTIVE']);expect(fn()=>app(MembershipService::class)->revoke($self,$actor,'Self removal attempt'))->toThrow(ValidationException::class);});
